/**
 * DEMO PHOTOGRAPHY — REPLACE BEFORE LAUNCH
 *
 * Every photo below is a free-licence Unsplash image standing in for real
 * Ammoun Sweets photography. They were chosen to match the shop's actual
 * products (pistachio baklava, knafeh, ashta sweets, gift trays) rather than
 * generic Western cakes — but they are NOT photos of Ammoun Sweets.
 *
 * All are free Unsplash License photos. Unsplash+ ("premium_photo") images are
 * deliberately excluded: they carry a visible watermark for non-subscribers
 * and are not free to reuse. If you add one, check the source URL is on
 * images.unsplash.com and NOT plus.unsplash.com.
 *
 * To swap in the owner's photos: drop a file with the same name into
 * /public/images (e.g. public/images/knafeh-ashta.jpg), update `width`,
 * `height` and `alt`, then delete its `credit` and `creditUrl` fields.
 * Nothing else in the codebase needs to change — see public/images/README.md.
 *
 * `blurDataURL` is a 16px LQIP so next/image can fade the photo in instead of
 * flashing empty space; `width`/`height` are the intrinsic pixel dimensions
 * and are what keep the layout from shifting as images load.
 *
 * Generated by scripts/gen-images-ts.mjs from scripts/images.manifest.json.
 */

export type SiteImage = {
  src: string;
  width: number;
  height: number;
  alt: string;
  blurDataURL: string;
  /** Attribution for the demo placeholder only. Remove with the real photos. */
  credit?: string;
  creditUrl?: string;
};

